(function(){function QRCode(el, options){var container=(typeof el==='string')?document.getElementById(el):el;if(!container)return;var text=(options&&options.text)||window.location.href;var size=(options&&options.width)||160;var img=document.createElement('img');img.alt='QR code for this page';img.width=size;img.height=size;img.src='https://api.qrserver.com/v1/create-qr-code/?size='+size+'x'+size+'&data='+encodeURIComponent(text);container.innerHTML='';container.appendChild(img);}QRCode.CorrectLevel={L:1,M:0,Q:3,H:2};window.QRCode=QRCode;})();